def find_medians(stream: list[int]) -> list[float]:
    import bisect
    sorted_list = []
    medians = []
    for x in stream:
        bisect.insort(sorted_list, x)
        n = len(sorted_list)
        if n % 2 == 1:
            medians.append(float(sorted_list[n // 2]))
        else:
            medians.append((sorted_list[n // 2 - 1] + sorted_list[n // 2]) / 2.0)
    return medians
